{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Human absolute bioavailability of saquinavir was only 4% (range 1–9%), a direct human F measurement far below the 20% threshold; high transferability supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Melagatran oral bioavailability was lowered to 0.9% after food intake in humans, directly relevant to the fed-state condition and well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Olcegepant had absolute oral bioavailability <1% in humans, demonstrating that a clinical-stage small molecule can be severely limited by low F; high transferability supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Revefenacin absolute oral bioavailability was <3% in healthy volunteers and COPD patients, another human absolute F result far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DX-9065a human oral bioavailability was only 2–3%, attributed to physicochemical limitations; highly transferable evidence supports low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable human evidence records report absolute or oral bioavailability below 10%, mostly 1–4%, far below the 20% threshold; no supportive evidence for high F. The fed-state condition does not change this conclusion.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "No structurally matched high-F comparator in the evidence set.",
    "Fed-state effect on the query's bioavailability is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

